import React from 'react';
import ReactDOM from 'react-dom/client';
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface PersistStore {
  count: number;
}

const usePersistStore = create(
  persist(
    (set) => ({
      count: 0
    }),
    {
      // Add persist configuration options here
    }
  )
);

const PersistDemo = () => {
  const { count } = usePersistStore();

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => usePersistStore.setState({ count: count + 1 })}>
        Increment
      </button>
    </div>
  );
};
